-- FUTASAKU — a permanent marker for test / verification traffic.
--
-- Why: the admin dashboard is meant to show REAL player activity only. Verification, rehearsal,
-- soak, load and simulation tooling talks to the same project the game does and created ordinary
-- players, matches, wallets and claims with no way to tell them apart from real play. `kind`
-- ('guest' | 'account') cannot help: a test guest is generated by the same generator a real guest
-- is, so historical rows could not be split by any existing column.
--
-- This is that missing marker. Additive and idempotent:
--   * both columns default to FALSE, so everything that already exists is "real" until the one-off
--     cleanup (server/scripts/clean-test-data.ts) explicitly marks the known test history;
--   * nothing reads or writes them on the gameplay path. The ONLY writers are the test tools
--     (server/scripts/mark-test-data.ts) and that cleanup, both by direct SQL. The public API has
--     no way to set it, so a real player can never mark themselves (nor anyone else) as test.
--
-- P-21 (the same lock-down as every other migration): the tables already have RLS on with no
-- anon/authenticated policies, so the two new columns inherit that — nothing extra is required.
--
-- NOT APPLIED YET. Apply with `npm run server:migrate`.

alter table players add column if not exists is_test boolean not null default false;
alter table matches add column if not exists is_test boolean not null default false;

-- Partial indexes: the dashboard's hot predicate is `is_test = false` (a full scan over a tiny
-- table is fine), while these make the two things that target the marker cheap — the cleanup's
-- "mark everything test" sweep and the operator's "show me what is marked" query.
create index if not exists players_is_test_idx on players (is_test) where is_test;
create index if not exists matches_is_test_idx on matches (is_test) where is_test;

comment on column players.is_test is
  'Permanent marker for test/verification traffic; set only by server/scripts tooling via SQL, never by the public API. Hidden from the admin dashboard.';
comment on column matches.is_test is
  'Permanent marker for test/verification traffic (set with the players it belongs to). Hidden from the admin dashboard.';
